26	export function usePrefersReducedMotion() {
27	  const [reduced, setReduced] = useState(false);
28	  useEffect(() => {
29	    const mq = window.matchMedia?.("(prefers-reduced-motion: reduce)");
30	    if (!mq) return;
31	    setReduced(mq.matches);
32	    const on = () => setReduced(mq.matches);
33	    mq.addEventListener?.("change", on);
34	    return () => mq.removeEventListener?.("change", on);
35	  }, []);
36	  return reduced;
37	}
38	
39	/** Fires once when the element first scrolls into view. */
40	export function useInViewOnce<T extends HTMLElement = HTMLDivElement>(margin = "0px 0px -12% 0px") {
41	  const ref = useRef<T | null>(null);
42	  const [seen, setSeen] = useState(false);
43	  useEffect(() => {
44	    const el = ref.current;
45	    if (!el || typeof IntersectionObserver === "undefined") {
46	      setSeen(true);
47	      return;
48	    }
49	    const io = new IntersectionObserver(
50	      ([e]) => {
51	        if (e.isIntersecting) {
52	          setSeen(true);
53	          io.disconnect();
54	        }
55	      },
56	      { threshold: 0.15, rootMargin: margin },
57	    );
58	    io.observe(el);
59	    return () => io.disconnect();
60	  }, [margin]);
61	  return { ref, seen };
62	}
63	
64	/**
65	 * Smoothly counts a number up to `target` once `active`. Under reduced motion
66	 * it returns the target immediately.
67	 */
68	export function useCountUp(target: number, active: boolean, duration = 1100, reduced = false) {
69	  const [val, setVal] = useState(reduced ? target : 0);
70	  useEffect(() => {
71	    if (!active) return;
72	    if (reduced) {
73	      setVal(target);
74	      return;
75	    }
76	    let raf = 0;
77	    const start = performance.now();
78	    const tick = (now: number) => {
79	      const t = Math.min(1, (now - start) / duration);
80	      const eased = 1 - Math.pow(1 - t, 3);
81	      setVal(Math.round(target * eased));
82	      if (t < 1) raf = requestAnimationFrame(tick);
83	    };
84	    raf = requestAnimationFrame(tick);
85	    return () => cancelAnimationFrame(raf);
86	  }, [target, active, duration, reduced]);
87	  return val;
88	}
89	
90	/**
91	 * A "live" integer that idles around a base value with small jitter, evoking a
92	 * ticking player count / TPS readout. Static (base) under reduced motion.
93	 */
94	export function useJitter(base: number, swing: number, active: boolean, ms = 2600, reduced = false) {
95	  const [val, setVal] = useState(base);
96	  useEffect(() => {
97	    if (!active || reduced) {
98	      setVal(base);
99	      return;
100	    }
101	    const id = window.setInterval(() => {
102	      if (document.hidden) return;
103	      const delta = Math.round((Math.random() - 0.45) * swing);
104	      setVal((v) => Math.max(base - swing, Math.min(base + swing, v + delta)));
105	    }, ms);
106	    return () => window.clearInterval(id);
107	  }, [base, swing, active, ms, reduced]);
108	  return val;
109	}
110	
111	/** Types out lines char-by-char once active. Returns fully-typed under reduced motion. */
112	export function useTypedLines(lines: string[], active: boolean, reduced = false) {
113	  const [done, setDone] = useState<string[]>(reduced || !active ? (active ? lines : []) : []);
114	  const [current, setCurrent] = useState("");
115	  const [caret, setCaret] = useState(reduced ? lines.length : 0);
116	  useEffect(() => {
117	    if (!active) return;
118	    if (reduced) {
119	      setDone(lines);
120	      setCaret(lines.length);
121	      return;
122	    }
123	    setDone([]);
124	    setCurrent("");
125	    setCaret(0);
126	    let li = 0;
127	    let ci = 0;
128	    let timer: ReturnType<typeof setTimeout>;
129	    const step = () => {
130	      if (li >= lines.length) return;
131	      const line = lines[li];
132	      if (ci <= line.length) {
133	        setCurrent(line.slice(0, ci));
134	        ci += 1;
135	        timer = setTimeout(step, 18 + Math.random() * 26);
136	      } else {
137	        setDone((d) => [...d, line]);
138	        setCaret(li + 1);
139	        li += 1;
140	        ci = 0;
141	        setCurrent("");
142	        timer = setTimeout(step, 340);
143	      }
144	    };
145	    timer = setTimeout(step, 500);
146	    return () => clearTimeout(timer);
147	  }, [active, reduced, lines]);
148	  return { done, current, caret };
149	}
150	
151	/**
152	 * Scroll-linked progress (0→1) for how far a section's top has travelled through
153	 * the viewport. Used for the editorial reason "spine". 0 under reduced motion is
154	 * fine — but we still want the spine full when the section is read, so it tracks
155	 * regardless and is just not animated by CSS.
156	 */
157	export function useScrollProgress<T extends HTMLElement = HTMLDivElement>() {
158	  const ref = useRef<T | null>(null);
159	  const [p, setP] = useState(0);
160	  useEffect(() => {
161	    const el = ref.current;
162	    if (!el) return;
163	    let raf = 0;
164	    const compute = () => {
165	      raf = 0;
166	      const r = el.getBoundingClientRect();
167	      const vh = window.innerHeight || 1;
168	      // 0 when the top hits 70% of viewport, 1 when the bottom passes 40%.
169	      const total = r.height + vh * 0.3;
170	      const travelled = vh * 0.7 - r.top;
171	      setP(Math.max(0, Math.min(1, travelled / total)));
172	    };
173	    const onScroll = () => {
174	      if (!raf) raf = requestAnimationFrame(compute);
175	    };
176	    compute();
177	    window.addEventListener("scroll", onScroll, { passive: true });
178	    window.addEventListener("resize", onScroll, { passive: true });
179	    return () => {
180	      window.removeEventListener("scroll", onScroll);
181	      window.removeEventListener("resize", onScroll);
182	      if (raf) cancelAnimationFrame(raf);
183	    };
184	  }, []);
185	  return { ref, p };
186	}
187	
188	/** Small parallax offset (px) driven by scroll, capped. Zero under reduced motion. */
189	export function useParallax<T extends HTMLElement = HTMLDivElement>(strength = 0.12, max = 60, reduced = false) {
190	  const ref = useRef<T | null>(null);
191	  const [y, setY] = useState(0);
192	  useEffect(() => {
193	    const el = ref.current;
194	    if (!el || reduced) return;
195	    let raf = 0;
196	    const compute = () => {
197	      raf = 0;
198	      const r = el.getBoundingClientRect();
199	      const vh = window.innerHeight || 1;
200	      const center = r.top + r.height / 2 - vh / 2;
201	      setY(Math.max(-max, Math.min(max, -center * strength)));
202	    };
203	    const onScroll = () => {
204	      if (!raf) raf = requestAnimationFrame(compute);
205	    };
206	    compute();
207	    window.addEventListener("scroll", onScroll, { passive: true });
208	    return () => {
209	      window.removeEventListener("scroll", onScroll);
210	      if (raf) cancelAnimationFrame(raf);
211	    };
212	  }, [strength, max, reduced]);
213	  return { ref, y };
214	}
