221	  terminal: IconTerminal,
222	  shield: IconShield,
223	  gauge: IconGauge,
224	  users: IconUsers,
225	  backup: IconBackup,
226	  globe: IconGlobe,
227	  scale: IconScale,
228	};
229	
230	export function ReasonIcon({ icon, size = 20, className }: { icon: IconKey; size?: number; className?: string }) {
231	  const C = ICONS[icon];
232	  return <C size={size} className={className} />;
233	}
