"use client";

/**
 * PREVIEW TEMPLATE 2 — Free-tier landing (the free Minecraft server).
 *
 * Leads on the Aternos-alternative wedge — "24/7. No queue. No ads." — and puts
 * the signature animated element front and centre: a live-looking FREE SERVER
 * card that SLEEPS, then WAKES ON JOIN (a player connects → boot progress →
 * online with a ticking player count), looping honestly. Around it: an honest
 * free-vs-paid table, a tasteful free→paid upgrade teaser (the conversion
 * bridge), a one-click "claim your free server" CTA, and compact 5-star reviews.
 *
 * Net-new, preview-only. Self-contained hooks. Every claim matches the LIVE
 * /free-minecraft page (genuinely free, 1 GB, ~15s wake, sleeps idle, no queue/
 * ads). Respects prefers-reduced-motion. Reuses only shared brand primitives and
 * the `pv-*` keyframes already in globals.css — adds no CSS.
 */

import Link from "next/link";
import { useEffect, useRef, useState } from "react";
import { GameLogo } from "@/components/marketing/GameLogo";
import { IconCheck, IconBolt, IconArrow, IconGift, IconUsers } from "@/components/marketing/icons";
import {
  CLAIM_HREF,
  UPGRADE_HREF,
  FREE_DOMAIN,
  SAMPLE_SUBDOMAIN,
  FREE_FEATURES,
  WEDGE,
  FREE_VS_PAID,
  UPGRADE_UNLOCKS,
  REVIEWS,
  RATING_AVG,
  RATING_LABEL,
  DISCLAIMER,
} from "./data";

/* ── self-contained motion hooks ─────────────────────────────────────────── */
function usePrefersReducedMotion() {
  const [reduced, setReduced] = useState(false);
  useEffect(() => {
    const mq = window.matchMedia?.("(prefers-reduced-motion: reduce)");
    if (!mq) return;
    setReduced(mq.matches);
    const on = () => setReduced(mq.matches);
    mq.addEventListener?.("change", on);
    return () => mq.removeEventListener?.("change", on);
  }, []);
  return reduced;
}

function useInViewOnce<T extends HTMLElement = HTMLDivElement>(margin = "0px 0px -12% 0px") {
  const ref = useRef<T | null>(null);
  const [seen, setSeen] = useState(false);
  useEffect(() => {
    const el = ref.current;
    if (!el || typeof IntersectionObserver === "undefined") {
      setSeen(true);
      return;
    }
    const io = new IntersectionObserver(
      ([e]) => {
        if (e.isIntersecting) {
          setSeen(true);
          io.disconnect();
        }
      },
      { threshold: 0.15, rootMargin: margin },
    );
    io.observe(el);
    return () => io.disconnect();
  }, [margin]);
  return { ref, seen };
}

/* ── atoms ───────────────────────────────────────────────────────────────── */
function StarRow({ rating = 5, size = "text-sm" }: { rating?: number; size?: string }) {
  const filled = Math.max(0, Math.min(5, rating));
  return (
    <span className={`tracking-[0.12em] ${size}`} aria-label={`${filled} out of 5 stars`}>
      <span className="text-amber-300">{"★".repeat(filled)}</span>
      <span className="text-white/15">{"★".repeat(5 - filled)}</span>
    </span>
  );
}

/* ── the signature: a free server that wakes on join ─────────────────────── */
type WakeState = "sleeping" | "joining" | "waking" | "online";

const JOINERS = ["Steve", "Alex", "leo_builds", "Mia"];

function FreeServerCard() {
  const reduced = usePrefersReducedMotion();
  const [state, setState] = useState<WakeState>("sleeping");
  const [pct, setPct] = useState(0);
  const [players, setPlayers] = useState(0);
  const [joiner, setJoiner] = useState(JOINERS[0]);
  const timers = useRef<ReturnType<typeof setTimeout>[]>([]);

  useEffect(() => {
    if (reduced) {
      // Rest on the finished, awake state — no loop, no motion.
      setState("online");
      setPct(100);
      setPlayers(3);
      return;
    }

    let cancelled = false;
    let round = 0;
    const wait = (ms: number) =>
      new Promise<void>((res) => {
        const t = setTimeout(res, ms);
        timers.current.push(t);
      });

    async function loop() {
      while (!cancelled) {
        // sleeping
        setState("sleeping");
        setPct(0);
        setPlayers(0);
        await wait(2600);
        if (cancelled) return;

        // a player connects → wakes it
        setJoiner(JOINERS[round % JOINERS.length]);
        setState("joining");
        await wait(1500);
        if (cancelled) return;

        // waking — boot progress
        setState("waking");
        for (let p = 0; p <= 100; p += 4) {
          if (cancelled) return;
          setPct(p);
          await wait(60);
        }
        if (cancelled) return;

        // online — players tick in
        setState("online");
        setPlayers(1);
        await wait(900);
        if (cancelled) return;
        setPlayers(2);
        await wait(1100);
        if (cancelled) return;
        setPlayers(3);
        await wait(3200);
        round += 1;
      }
    }

    loop();
    return () => {
      cancelled = true;
      timers.current.forEach(clearTimeout);
      timers.current = [];
    };
  }, [reduced]);

  const awake = state === "online";
  const statusLabel =
    state === "sleeping" ? "sleeping" : state === "joining" ? "waking…" : state === "waking" ? "starting" : "online";
  const statusTone =
    state === "online"
      ? "bg-emerald-500/12 text-emerald-300"
      : state === "sleeping"
        ? "bg-white/[0.05] text-slate-400"
        : "bg-accent-cyan/12 text-accent-cyan";

  return (
    <div className={reduced ? "" : "pv-float"}>
      <div className="relative overflow-hidden rounded-3xl border border-white/10 bg-[#080d18]/90 shadow-2xl shadow-black/50 backdrop-blur-xl">
        {/* ambient accent */}
        <div
          className="pointer-events-none absolute -inset-16 -z-10 transition-opacity duration-700"
          style={{
            opacity: awake ? 0.8 : 0.3,
            background: "radial-gradient(45% 45% at 80% 0%, rgba(34,211,238,0.22), transparent 70%)",
          }}
          aria-hidden
        />

        {/* header — address + status */}
        <div className="flex items-center gap-2.5 border-b border-white/[0.06] bg-white/[0.02] px-4 py-3">
          <GameLogo family="minecraft" size={24} />
          <span className="truncate font-mono text-[12px] text-slate-300">
            {SAMPLE_SUBDOMAIN}.{FREE_DOMAIN}
          </span>
          <span
            className={`ml-auto inline-flex shrink-0 items-center gap-1.5 rounded-full px-2 py-0.5 text-[10px] font-semibold uppercase tracking-wide ${statusTone}`}
          >
            <span
              className={`h-1.5 w-1.5 rounded-full ${awake ? "bg-emerald-400 motion-safe:animate-pulse-dot" : state === "sleeping" ? "bg-slate-500" : "bg-accent-cyan motion-safe:animate-pulse-dot"}`}
            />
            {statusLabel}
          </span>
        </div>

        {/* world viewport — real key art, dimmed while asleep */}
        <div className="relative aspect-[16/10] overflow-hidden">
          {/* eslint-disable-next-line @next/next/no-img-element */}
          <img
            src="/games/art/minecraft_hero.jpg"
            alt="Minecraft world"
            className="h-full w-full object-cover object-center transition-all duration-700"
            style={{ filter: awake ? "none" : "grayscale(0.5) brightness(0.4)", transform: awake ? "scale(1.02)" : "scale(1)" }}
          />
          <div className="pointer-events-none absolute inset-0 bg-gradient-to-t from-[#080d18] via-transparent to-transparent" aria-hidden />

          {/* state overlay */}
          <div className="absolute inset-0 flex flex-col items-center justify-center p-6 text-center">
            {state === "sleeping" && (
              <>
                <span className="text-3xl" aria-hidden>💤</span>
                <p className="mt-2 text-sm font-semibold text-slate-200">Sleeping to save resources</p>
                <p className="mt-1 text-[12px] text-slate-400">A player joining wakes it in ~15 seconds.</p>
              </>
            )}
            {state === "joining" && (
              <>
                <span className="relative flex h-11 w-11 items-center justify-center">
                  <span className="absolute inset-0 rounded-full border-2 border-accent-cyan/20" />
                  <span className="absolute inset-0 rounded-full border-2 border-transparent border-t-accent-cyan motion-safe:animate-spin" />
                  <IconUsers size={18} />
                </span>
                <p className="mt-3 text-sm font-semibold text-white">
                  <span className="text-accent-cyan">{joiner}</span> is connecting…
                </p>
                <p className="mt-1 text-[12px] text-slate-400">Waking your server.</p>
              </>
            )}
            {state === "waking" && (
              <div className="w-full max-w-xs">
                <p className="text-sm font-semibold text-white">
                  {pct < 45 ? "Waking your server…" : pct < 85 ? "Loading world…" : "Almost there…"}
                </p>
                <div className="mt-3 h-2 w-full overflow-hidden rounded-full bg-white/10">
                  <div
                    className="h-full rounded-full bg-gradient-to-r from-accent-blue to-accent-cyan transition-[width] duration-75 ease-linear"
                    style={{ width: `${pct}%` }}
                  />
                </div>
                <p className="mt-1.5 text-right font-mono text-[11px] text-slate-400">{pct}%</p>
              </div>
            )}
            {state === "online" && (
              <>
                <span className="flex h-12 w-12 items-center justify-center rounded-full bg-emerald-500/15 text-emerald-300 ring-1 ring-emerald-500/30">
                  <IconCheck size={24} />
                </span>
                <p className="mt-3 text-base font-semibold text-white">Online &amp; ready</p>
                <p className="mt-1 text-[12px] text-slate-300">Connect on the standard port — no queue.</p>
              </>
            )}
          </div>
        </div>

        {/* footer — players + spec */}
        <div className="flex items-center justify-between gap-3 px-4 py-3.5">
          <div className="flex items-center gap-2.5">
            <div className="flex -space-x-2">
              {Array.from({ length: 3 }).map((_, i) => (
                <span
                  key={i}
                  className="h-6 w-6 rounded-full border-2 border-[#080d18] bg-gradient-to-br from-accent-cyan to-brand-500 transition-all duration-300"
                  style={{ opacity: i < players ? 1 : 0.15, transform: i < players ? "scale(1)" : "scale(0.7)" }}
                  aria-hidden
                />
              ))}
            </div>
            <span className="font-mono text-[12px] text-slate-400 tabular-nums">
              {players} {players === 1 ? "player" : "players"} online
            </span>
          </div>
          <span className="rounded-md bg-white/[0.05] px-2 py-1 font-mono text-[11px] text-slate-400">1 GB · free</span>
        </div>
      </div>

      {/* honest caption */}
      <p className="mt-3 text-center text-[11px] text-slate-500">
        Live demo — a real free server sleeps when empty and wakes the moment someone connects.
      </p>
    </div>
  );
}

/* ── main ────────────────────────────────────────────────────────────────── */
export function FreeTierTemplate() {
  return (
    <div className="relative">
      {/* ── HERO ─────────────────────────────────────────────────────────── */}
      <section className="relative isolate overflow-hidden">
        {/* faint real key-art backdrop */}
        <div className="absolute inset-0 -z-20 overflow-hidden" aria-hidden>
          {/* eslint-disable-next-line @next/next/no-img-element */}
          <img
            src="/games/art/minecraft_hero.jpg"
            alt=""
            className="h-full w-full scale-110 object-cover object-center opacity-[0.12]"
          />
        </div>
        <div className="pointer-events-none absolute inset-0 -z-10 bg-gradient-to-b from-navy-950/70 via-navy-950/85 to-navy-950" aria-hidden />
        <div className="pointer-events-none absolute inset-0 -z-10 hero-aura" aria-hidden />

        <div className="rail grid items-center gap-12 py-20 lg:grid-cols-12 lg:gap-10 lg:py-28">
          <div className="lg:col-span-6">
            <span className="eyebrow-pill">
              <IconGift size={13} /> Free Minecraft hosting
            </span>
            <h1 className="mt-5 text-4xl font-bold leading-[1.03] tracking-tight text-white sm:text-5xl xl:text-6xl">
              24/7. No queue. <span className="grad-text">No ads.</span>
            </h1>
            <p className="mt-6 max-w-xl text-lg leading-relaxed text-slate-300/90">
              A genuinely free Minecraft server on your own subdomain — {SAMPLE_SUBDOMAIN}.{FREE_DOMAIN}.
              It sleeps when nobody&apos;s playing and wakes the moment someone connects. No credit card,
              no line to wait in, no ad screen.
            </p>

            <div className="mt-8 flex flex-wrap items-center gap-3">
              <Link href={CLAIM_HREF} className="btn-deploy px-6 py-3 text-base">
                Claim your free server
                <span className="dep-arrow" aria-hidden>→</span>
              </Link>
              <a href="#free-vs-paid" className="btn-secondary px-5 py-3 text-base">
                Free vs paid
              </a>
            </div>

            {/* honest micro-proof row */}
            <div className="mt-7 flex flex-wrap items-center gap-x-5 gap-y-2 text-sm text-slate-400">
              <span className="inline-flex items-center gap-2">
                <StarRow rating={5} />
                <span>
                  <span className="font-semibold text-white">{RATING_AVG}</span> {RATING_LABEL}
                </span>
              </span>
              <span className="inline-flex items-center gap-1.5">
                <IconCheck size={15} className="text-accent-cyan" /> No credit card
              </span>
            </div>
          </div>

          <div className="lg:col-span-6 lg:pl-6">
            <FreeServerCard />
          </div>
        </div>
      </section>

      {/* ── WHAT FREE GETS YOU ───────────────────────────────────────────── */}
      <section className="rail py-24">
        <div className="max-w-2xl">
          <span className="eyebrow">What you actually get</span>
          <h2 className="mt-3 text-3xl font-bold tracking-tight text-white sm:text-4xl">
            A real server, not a demo
          </h2>
        </div>
        <div className="mt-12 grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
          {FREE_FEATURES.map((f, i) => (
            <FeatureCard key={f.title} f={f} delay={i * 70} />
          ))}
        </div>
      </section>

      {/* ── THE ATERNOS WEDGE ────────────────────────────────────────────── */}
      <section className="tone-panel py-24">
        <div className="rail">
          <div className="max-w-2xl">
            <span className="eyebrow">Why it feels premium</span>
            <h2 className="mt-3 text-3xl font-bold tracking-tight text-white sm:text-4xl">
              Free, without the free-host baggage
            </h2>
            <p className="mt-4 text-lg text-slate-400">
              Most free Minecraft hosting funds itself with a queue and an ad screen. Ours doesn&apos;t — here&apos;s
              the honest difference.
            </p>
          </div>
          <div className="mt-12 grid gap-4 md:grid-cols-3">
            {WEDGE.map((w, i) => (
              <WedgeCard key={w.tag} w={w} delay={i * 80} />
            ))}
          </div>
          <p className="mt-6 max-w-3xl text-[11px] leading-relaxed text-slate-600">{DISCLAIMER}</p>
        </div>
      </section>

      {/* ── FREE VS PAID ─────────────────────────────────────────────────── */}
      <section id="free-vs-paid" className="rail py-24 scroll-mt-24">
        <div className="mx-auto max-w-2xl text-center">
          <span className="eyebrow">Free vs paid</span>
          <h2 className="mt-3 text-3xl font-bold tracking-tight text-white sm:text-4xl">
            Stay free forever, or grow into more
          </h2>
          <p className="mt-4 text-lg text-slate-400">
            The free tier is genuinely free and honestly limited. When you outgrow it, upgrading is one click
            on the same account.
          </p>
        </div>

        <div className="mx-auto mt-12 max-w-3xl overflow-hidden rounded-3xl border border-white/[0.08] bg-navy-900/60 backdrop-blur-md">
          {/* header */}
          <div className="grid grid-cols-[1.1fr_1fr_1fr] border-b border-white/[0.08] text-[11px] font-semibold uppercase tracking-wider">
            <span className="px-5 py-4 text-slate-500">Compared</span>
            <span className="px-5 py-4 text-accent-cyan">Free</span>
            <span className="bg-brand-500/[0.06] px-5 py-4 text-brand-200">Paid</span>
          </div>
          {FREE_VS_PAID.map((line) => (
            <div
              key={line.label}
              className="grid grid-cols-[1.1fr_1fr_1fr] border-b border-white/[0.05] text-[13px] last:border-0"
            >
              <span className="px-5 py-3.5 font-medium text-white">{line.label}</span>
              <span className="px-5 py-3.5 text-slate-300">{line.free}</span>
              <span className="flex items-center gap-1.5 bg-brand-500/[0.04] px-5 py-3.5 text-slate-200">
                {line.paidWin && (
                  <span className="flex h-4 w-4 shrink-0 items-center justify-center rounded-full bg-brand-500/20 text-brand-200">
                    <IconArrow size={11} />
                  </span>
                )}
                {line.paid}
              </span>
            </div>
          ))}
        </div>

        <div className="mt-8 flex flex-wrap justify-center gap-3">
          <Link href={CLAIM_HREF} className="btn-deploy px-6 py-3 text-base">
            Start free
            <span className="dep-arrow" aria-hidden>→</span>
          </Link>
          <Link href={UPGRADE_HREF} className="btn-secondary px-6 py-3 text-base">
            See paid plans
          </Link>
        </div>
      </section>

      {/* ── UPGRADE TEASER (conversion bridge) ───────────────────────────── */}
      <section className="tone-deep py-24">
        <div className="rail">
          <div className="relative overflow-hidden rounded-3xl border border-brand-500/25 bg-gradient-to-br from-brand-500/[0.10] via-navy-900/60 to-navy-900/60 p-8 backdrop-blur-md sm:p-12">
            <div
              className="pointer-events-none absolute -right-24 -top-24 h-64 w-64 rounded-full blur-3xl"
              style={{ background: "rgba(111,71,245,0.22)" }}
              aria-hidden
            />
            <div className="grid gap-10 lg:grid-cols-[1fr_1.3fr] lg:items-center">
              <div>
                <span className="eyebrow">Ready for more?</span>
                <h2 className="mt-3 text-3xl font-bold leading-tight tracking-tight text-white sm:text-4xl">
                  What you unlock by <span className="grad-text">upgrading</span>
                </h2>
                <p className="mt-4 text-slate-300/90">
                  Keep your world and your account — a paid server just removes the limits.
                </p>
                <Link href={UPGRADE_HREF} className="btn-deploy mt-7 inline-flex px-6 py-3 text-base">
                  Explore paid plans
                  <span className="dep-arrow" aria-hidden>→</span>
                </Link>
              </div>
              <div className="grid gap-3 sm:grid-cols-2">
                {UPGRADE_UNLOCKS.map((u) => (
                  <div key={u.title} className="rounded-2xl border border-white/[0.08] bg-white/[0.03] p-5">
                    <span className="flex h-9 w-9 items-center justify-center rounded-xl bg-brand-500/15 text-brand-200">
                      <IconBolt size={18} />
                    </span>
                    <h3 className="mt-3 text-[15px] font-semibold text-white">{u.title}</h3>
                    <p className="mt-1.5 text-[13px] leading-relaxed text-slate-400">{u.body}</p>
                  </div>
                ))}
              </div>
            </div>
          </div>
        </div>
      </section>

      {/* ── REVIEWS ──────────────────────────────────────────────────────── */}
      <section className="rail py-24">
        <div className="mx-auto max-w-2xl text-center">
          <div className="flex items-center justify-center gap-3">
            <StarRow rating={5} size="text-base" />
            <span className="text-sm text-slate-400">
              <span className="font-semibold text-white">{RATING_AVG} / 5</span> average
            </span>
          </div>
          <h2 className="mt-4 text-3xl font-bold tracking-tight text-white sm:text-4xl">Loved by free-tier players</h2>
        </div>
        <div className="mt-12 grid gap-4 md:grid-cols-3">
          {REVIEWS.map((rv) => (
            <figure key={rv.id} className="card flex flex-col">
              <StarRow rating={rv.rating} />
              <blockquote className="mt-4 flex-1 text-sm leading-relaxed text-slate-300">&ldquo;{rv.quote}&rdquo;</blockquote>
              <figcaption className="mt-5 flex items-center gap-3 border-t border-white/[0.06] pt-4">
                <span className="flex h-9 w-9 items-center justify-center rounded-full bg-gradient-to-br from-accent-cyan to-brand-500 text-sm font-semibold text-white">
                  {rv.name.charAt(0).toUpperCase()}
                </span>
                <span>
                  <span className="block text-sm font-semibold text-white">{rv.name}</span>
                  <span className="block text-xs text-slate-500">{rv.meta}</span>
                </span>
              </figcaption>
            </figure>
          ))}
        </div>
      </section>

      {/* ── CLAIM CTA ────────────────────────────────────────────────────── */}
      <section className="tone-panel py-24">
        <div className="rail text-center">
          <h2 className="mx-auto max-w-3xl text-3xl font-bold leading-tight tracking-tight text-white sm:text-5xl">
            Your free Minecraft server is one <span className="grad-text">click</span> away.
          </h2>
          <p className="mx-auto mt-5 max-w-xl text-lg text-slate-300">
            Pick a name, and it&apos;s live at {SAMPLE_SUBDOMAIN}.{FREE_DOMAIN}. No credit card, no queue, no ads.
          </p>
          <div className="mt-9 flex flex-wrap justify-center gap-3">
            <Link href={CLAIM_HREF} className="btn-deploy px-7 py-3.5 text-base">
              Claim your free server
              <span className="dep-arrow" aria-hidden>→</span>
            </Link>
            <Link href={UPGRADE_HREF} className="btn-secondary px-6 py-3.5 text-base">
              See paid plans
            </Link>
          </div>
        </div>
      </section>
    </div>
  );
}

/* ── sub-components ──────────────────────────────────────────────────────── */
function FeatureCard({ f, delay }: { f: { title: string; body: string }; delay: number }) {
  const { ref, seen } = useInViewOnce<HTMLDivElement>();
  return (
    <div
      ref={ref}
      className="flex flex-col rounded-2xl border border-white/[0.07] bg-navy-900/60 p-5 backdrop-blur-md transition-all duration-700 ease-out"
      style={{
        transitionDelay: `${delay}ms`,
        opacity: seen ? 1 : 0,
        transform: seen ? "translateY(0)" : "translateY(16px)",
      }}
    >
      <span className="flex h-9 w-9 items-center justify-center rounded-xl bg-accent-cyan/12 text-accent-cyan">
        <IconCheck size={18} />
      </span>
      <h3 className="mt-4 text-[15px] font-semibold text-white">{f.title}</h3>
      <p className="mt-1.5 text-[13px] leading-relaxed text-slate-400">{f.body}</p>
    </div>
  );
}

function WedgeCard({ w, delay }: { w: { tag: string; title: string; body: string }; delay: number }) {
  const { ref, seen } = useInViewOnce<HTMLDivElement>();
  return (
    <div
      ref={ref}
      className="group relative flex flex-col overflow-hidden rounded-2xl border border-white/[0.07] bg-navy-900/60 p-6 backdrop-blur-md transition-all duration-700 ease-out hover:border-white/15"
      style={{
        transitionDelay: `${delay}ms`,
        opacity: seen ? 1 : 0,
        transform: seen ? "translateY(0)" : "translateY(16px)",
      }}
    >
      <span className="inline-flex w-fit items-center gap-1.5 rounded-full bg-accent-cyan/12 px-2.5 py-1 text-[11px] font-semibold uppercase tracking-wide text-accent-cyan">
        {w.tag}
      </span>
      <h3 className="mt-4 text-lg font-semibold text-white">{w.title}</h3>
      <p className="mt-2 text-sm leading-relaxed text-slate-400">{w.body}</p>
    </div>
  );
}

